INSERT INTO helpline_wording (row_id, unique_row, old_key, new_key, fields, en, note)
VALUES
  (13, true, '13|||קווי סיוע והכוונה', '13|||רשימת מוקדי עזרה ראשונה נפשית.', '{"org":"בנפש בריאה, משרד הבריאות","svc":"רשימת מוקדי עזרה ראשונה נפשית.","target":"","region":"","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"המוקדים עצמם בכרטיסים נפרדים. במצוקה קיצונית פונים למיון בבית חולים פסיכיאטרי, ללא עלות וללא הפניה.","meeting":"","web":"https://me.health.gov.il/mental-health/therapy-rehabilitation/crisis-support/first-aid/","add":"","addLabel":"","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"In a Healthy Mind, Ministry of Health","svc":"A list of mental-health first-aid lines.","notes":"The lines themselves are on separate cards. In extreme distress, go to a psychiatric hospital emergency room, at no cost and with no referral.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '27.11.2026: נבדק מול עמוד העזרה הראשונה בבנפש בריאה, עודכן 21.10.2026. *5400 הוא יצירת קשר עם המשרד, ולא עלה. רשימת השפות ירדה. הניסוח אושר עם אצוות קווי הסיוע.'),
  (14, true, '14|||רשימת מוקדי הטיפול ומרכזי החוסן', '14|||ליווי וסיוע בזכויות לנפגעי איבה ולמשפחותיהם. בטלפון.', '{"org":"ביטוח לאומי","svc":"ליווי וסיוע בזכויות לנפגעי איבה ולמשפחותיהם. בטלפון.","target":"נפגעי פעולות איבה, פצועים ובני משפחותיהם","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"עובד שיקום מלווה את הנפגע ואת המשפחה. מרכזי החוסן בכרטיס נפרד.","meeting":"","web":"https://www.btl.gov.il/benefits/Victims_of_hostilities/Pages/default.aspx","add":"https://www.btl.gov.il/HaravotBarzel1/Harada_HB/Pages/MrkaziHosenResima.aspx","addLabel":"מרכזי החוסן","phone":"02-6269999","phoneLabel":"קו חירום","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"National Insurance Institute","svc":"Accompaniment and assistance with rights for victims of hostilities and their families. By phone.","target":"Victims of hostilities, people who were wounded, and their family members","region":"Nationwide","notes":"A rehabilitation social worker accompanies the person and the family. Resilience centers are on a separate card.","phone":"02-6269999","phoneLabel":"Emergency line","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","addLabel":"Resilience centers"}'::jsonb, '27.11.2026: נבדק מול עמוד נפגעי פעולות איבה בביטוח לאומי. השעות סותרות בין ידיעות 2023 ו-2025, ולא עלו. *6050 הוא המוקד הכללי, ולא עלה. הקישור למרכזי החוסן נשאר. הניסוח אושר עם אצוות קווי הסיוע.'),
  (15, false, '15|||מוקד סיוע רגשי-חברתי להורים ולתלמידים', '15|||תמיכה רגשית וחברתית במצוקה, בדחייה חברתית ובחרם. בטלפון או בטופס.', '{"org":"קול לכולם, משרד החינוך","svc":"תמיכה רגשית וחברתית במצוקה, בדחייה חברתית ובחרם. בטלפון או בטופס.","target":"תלמידים, הורים ואנשי חינוך","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"המוקד של השירות הפסיכולוגי ייעוצי. אפשר גם פנייה אנונימית בטופס. במקרים הרלוונטיים הטיפול עובר לצוות בית הספר.","meeting":"","web":"https://www.gov.il/he/pages/protection","add":"","addLabel":"","phone":"*6312","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Kol Lekulam, Ministry of Education","svc":"Emotional and social support in distress, social rejection, and ostracism. By phone or in a form.","target":"Students, parents, and education staff","region":"Nationwide","notes":"The hotline of the school psychology service. An anonymous form is also possible. In the relevant cases the care passes to the school staff.","phone":"*6312","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '27.11.2026: נבדק מול https://www.gov.il/he/pages/protection ודף השירות. השם עכשיו קול לכולם. השעות א-ה ויום ו לא עלו. כרטיס משרד הבריאות באותה שורה לא נגע. הניסוח אושר עם אצוות קווי הסיוע.'),
  (21, false, '21|||תמיכה נפשית ותעסוקתית לנפגעי טראומה ממלחמה וטרור', '21|||עזרה ראשונה נפשית אנונימית לנפגעי טראומה ממלחמה וטרור, 24/7. בטלפון.', '{"org":"נט״ל","svc":"עזרה ראשונה נפשית אנונימית לנפגעי טראומה ממלחמה וטרור, 24/7. בטלפון.","target":"נפגעי טראומה על רקע מלחמה וטרור, ובני משפחותיהם","region":"כל הארץ","cost":"ללא עלות","specialty":"","approaches":"","languages":"","diseases":"","notes":"גם צ׳אט באתר. אפשר לפנות בעילום שם, חוץ ממקרה חירום.","meeting":"","web":"https://www.natal.org.il/קו-הסיוע-של-נטל/","add":"","addLabel":"","phone":"*3362","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Natal","svc":"Anonymous mental-health first aid for people with trauma from war and terror, 24/7. By phone.","target":"People with trauma from war and terror, and their family members","region":"Nationwide","cost":"At no cost","notes":"Also a chat on the site. It is possible to call without giving a name, except in an emergency.","phone":"*3362","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '27.11.2026: נבדק מול עמוד קו הסיוע של נט״ל. *3362, 24/7, ללא עלות. דף משרד הבריאות עדיין כותב 1-800-363-363, והמספר לא עלה. רי״ל באותה שורה לא נגע. הניסוח אושר עם אצוות קווי הסיוע.'),
  (22, true, '22|||קו סיוע והכוונה', '22|||תמיכה נפשית אנונימית, 24/7. בצ׳אט.', '{"org":"סהר","svc":"תמיכה נפשית אנונימית, 24/7. בצ׳אט.","target":"כל אדם","region":"כל הארץ","founded":"2000","cost":"ללא עלות","specialty":"","approaches":"","languages":"עברית, ערבית","diseases":"","notes":"גם בוואטסאפ, מהכפתור באתר. בוואטסאפ השם והמספר נראים למתנדב.","meeting":"","web":"https://sahar.org.il/","add":"","addLabel":"","phone":"","phoneLabel":"","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Sahar","svc":"Anonymous mental-health support, 24/7. In a chat.","target":"Any person","region":"Nationwide","founded":"2000","cost":"At no cost","languages":"Hebrew, Arabic","notes":"Also on WhatsApp, from the button on the site. On WhatsApp the name and the number are visible to the volunteer.","phone":"","phoneLabel":"","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '27.11.2026: נבדק מול https://sahar.org.il/ ודף העזרה. אין מספר וואטסאפ מפורסם. הצ׳אט כתוב 24/7, ושעות משמרת באותו עמוד לא עלו. הוקם 2000 מעמוד האודות. הניסוח אושר עם אצוות קווי הסיוע.'),
  (24, true, '24|||מוקדי סיוע
מרכז טיפול
ועוד', '24|||סיוע רגשי, זוגי ומשפחתי, 24/6. בטלפון.', '{"org":"מטיבת״א","svc":"סיוע רגשי, זוגי ומשפחתי, 24/6. בטלפון.","target":"הציבור הדתי והחרדי","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"גם התאמת מטפל. לחיות, ולמטיב המרכז לטראומה, בכרטיסים נפרדים.","meeting":"","web":"https://metivta.org.il/","add":"","addLabel":"","phone":"*2837","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Metivta","svc":"Emotional, couple, and family assistance, 24/6. By phone.","target":"The religious and Haredi public","region":"Nationwide","notes":"Also matching with a therapist. Lichyot, and Metiv the trauma center, are on separate cards.","phone":"*2837","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '27.11.2026: נבדק מול https://metivta.org.il/. *2837, 24/6 בכותרת. לא מוזג עם לחיות או עם מטיב. הניסוח אושר עם אצוות קווי הסיוע.'),
  (25, true, '25|||תמיכה ואוזן קשבת לבני משפחה למתמודדי נפש', '25|||תמיכה ואוזן קשבת לבני משפחה של מתמודדי נפש. בטלפון.', '{"org":"מוקד CALL לנפש","svc":"תמיכה ואוזן קשבת לבני משפחה של מתמודדי נפש. בטלפון.","target":"בני משפחה של מתמודדי נפש","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"","meeting":"","web":"https://cbh.org.il/%D7%A7%D7%91%D7%9C%D7%AA-%D7%A2%D7%96%D7%A8%D7%94/","add":"","addLabel":"","phone":"*8246","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"office@homiyacbh.org","emailLabel":"אימייל","emailShowAddress":false}'::jsonb, '{"org":"CALL Lanefesh hotline","svc":"Support and a listening ear for family members of people coping with mental illness. By phone.","target":"Family members of people coping with mental illness","region":"Nationwide","phone":"*8246","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"office@homiyacbh.org","emailLabel":"Email"}'::jsonb, '27.11.2026: עמוד העזרה לא נפתח. הפרטים מעמודי האתר עצמם: *8246 ו-office@homiyacbh.org. השעות סותרות בין העמודים, ולא עלו. וואטסאפ מפוסט ישן ו-*6947 לא עלו. הניסוח אושר עם אצוות קווי הסיוע.'),
  (26, true, '26|||קו ייעוץ ותמיכה - בימים א-ה בשעות 10:00-13:00 ו-16:00-22:00', '26|||תמיכה, ייעוץ והכוונה בזמן מצוקה נפשית. בטלפון.', '{"org":"ידידי נפש (עזר מציון)","svc":"תמיכה, ייעוץ והכוונה בזמן מצוקה נפשית. בטלפון.","target":"כל אדם","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"אפשר לפנות בלי להזדהות. בשעת חירום נפתח קו נוסף, 1-800-808-100. המשרד ברב רבינוב 5, בני ברק.","meeting":"","web":"https://www.ami.org.il/services/mental-counseling","add":"","addLabel":"","phone":"1-800-30-30-12","phoneLabel":"טלפון","phoneShowNumber":false,"phone2":"","phoneLabel2":"","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Yedidei Nefesh (Ezer Mizion)","svc":"Support, counseling, and guidance during mental distress. By phone.","target":"Any person","region":"Nationwide","notes":"It is possible to call without identifying yourself. In a national emergency an additional line opens, 1-800-808-100. The office is at 5 Rav Rabinow, Bnei Brak.","phone":"1-800-30-30-12","phoneLabel":"Phone","phone2":"","phoneLabel2":"","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '27.11.2026: נבדק מול https://www.ami.org.il/services/mental-counseling. שעות הקו ומספרי התרומות ירדו. קו החירום נשאר בהערות. העמוד אינו כותב ללא עלות. הניסוח אושר עם אצוות קווי הסיוע.'),
  (60, true, '60|||מידע, ייעוץ ותמיכה
מרכזי טיפול
מרכזי שיקום', '60|||שיקום וטיפול למתמודדים עם אתגר נפשי, וגם ייעוץ ותמיכה. במרכז או בטלפון.', '{"org":"עמותת בית חם","svc":"שיקום וטיפול למתמודדים עם אתגר נפשי, וגם ייעוץ ותמיכה. במרכז או בטלפון.","target":"מתמודדים עם אתגר נפשי, ובני משפחותיהם","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"קו קשובים, עם קו לגברים וקו לנשים, בכרטיס נפרד.","meeting":"in_person","web":"https://www.bayit-cham.org.il/","add":"","addLabel":"","phone":"*9518","phoneLabel":"ייעוץ","phoneShowNumber":false,"phone2":"1599-510-550","phoneLabel2":"ייעוץ","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Bayit Cham association","svc":"Rehabilitation and treatment for people coping with a mental challenge, and also counseling and support. At a center or by phone.","target":"People coping with a mental challenge, and their family members","region":"Nationwide","notes":"The Keshuviim line, with a line for men and a line for women, is on a separate card.","meeting":"in_person","phone":"*9518","phoneLabel":"Counseling","phone2":"1599-510-550","phoneLabel2":"Counseling","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '27.11.2026: נבדק מול https://www.bayit-cham.org.il/. שני המספרים הם אותו קו ייעוץ. אנגלית לא נמצאה, והשפה ירדה. הניסוח אושר עם אצוות קווי הסיוע.'),
  (61, true, '61|||מידע, ייעוץ ותמיכה', '61|||מידע ותמיכה למי שנתקל בקושי נפשי. בטלפון.', '{"org":"קשובים, בית חם","svc":"מידע ותמיכה למי שנתקל בקושי נפשי. בטלפון.","target":"","region":"כל הארץ","cost":"","specialty":"","approaches":"","languages":"","diseases":"","notes":"קו לגברים, אוזן קשבת, וקו לנשים, מלב אל לב. המענה דיסקרטי, מאנשי מקצוע.","meeting":"","web":"https://www.bayit-cham.org.il/%D7%A7%D7%95%D7%95%D7%99-%D7%99%D7%99%D7%A2%D7%95%D7%A5-%D7%A7%D7%A9%D7%95%D7%91%D7%99%D7%9D/","add":"","addLabel":"","phone":"*9518","phoneLabel":"קשובים","phoneShowNumber":false,"phone2":"1599-510-550","phoneLabel2":"קשובים","phoneShowNumber2":false,"phone3":"","phoneLabel3":"","phoneShowNumber3":false,"phone4":"","phoneLabel4":"","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false}'::jsonb, '{"org":"Keshuviim, Bayit Cham","svc":"Information and support for a person who has run into a mental difficulty. By phone.","region":"Nationwide","notes":"A line for men, Ozen Kashevet, and a line for women, Milev El Lev. The response is discreet, from professionals.","phone":"*9518","phoneLabel":"Keshuviim","phone2":"1599-510-550","phoneLabel2":"Keshuviim","phone3":"","phoneLabel3":"","phone4":"","phoneLabel4":"","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":""}'::jsonb, '27.11.2026: נבדק מול עמוד קווי הייעוץ קשובים. 9518* נשמר כ-*9518. המייל של מנהלת השירות לא עלה. הניסוח אושר עם אצוות קווי הסיוע.'),
  (63, true, '63|||תמיכה לנוער וצעירים', '63|||טיפול רגשי ממוקד לנוער ולצעירים. במרכז.', '{"org":"הדספייס","svc":"טיפול רגשי ממוקד לנוער ולצעירים. במרכז.","target":"נוער וצעירים בגילאי 10 עד 25","region":"בת ים, ירושלים","cost":"ללא תשלום ישיר. בחלק מהמקרים נדרשת התחייבות מקופת החולים.","specialty":"","approaches":"","languages":"","diseases":"","notes":"רוטשילד 29, בת ים. פייר קינג 33, ירושלים. יש גם מפגשים מרחוק. אפשר גם וואטסאפ למספרים של בת ים ושל ירושלים.","meeting":"in_person","web":"https://headspace.org.il/","add":"","addLabel":"","phone":"050-9693460","phoneLabel":"כללי","phoneShowNumber":false,"phone2":"054-9299723","phoneLabel2":"בת ים","phoneShowNumber2":false,"phone3":"03-5040900","phoneLabel3":"בת ים","phoneShowNumber3":false,"phone4":"054-9299740","phoneLabel4":"ירושלים","phoneShowNumber4":false,"phone5":"","phoneLabel5":"","phoneShowNumber5":false,"phone6":"","phoneLabel6":"","phoneShowNumber6":false,"email":"info@headspace.org.il","emailLabel":"כללי","emailShowAddress":false,"email2":"kabala@headspace.org.il","emailLabel2":"בת ים","emailShowAddress2":false,"email3":"jerusalem@headspace.org.il","emailLabel3":"ירושלים","emailShowAddress3":false}'::jsonb, '{"org":"Headspace","svc":"Focused emotional treatment for youth and young adults. At the center.","target":"Youth and young adults aged 10 to 25","region":"Bat Yam, Jerusalem","cost":"No direct payment. In some cases a health-fund commitment form is required.","notes":"29 Rothschild, Bat Yam. 33 Pierre Koenig, Jerusalem. There are also remote meetings. WhatsApp is also possible on the Bat Yam and Jerusalem numbers.","meeting":"in_person","phone":"050-9693460","phoneLabel":"General","phone2":"054-9299723","phoneLabel2":"Bat Yam","phone3":"03-5040900","phoneLabel3":"Bat Yam","phone4":"054-9299740","phoneLabel4":"Jerusalem","phone5":"","phoneLabel5":"","phone6":"","phoneLabel6":"","email":"info@headspace.org.il","emailLabel":"General","email2":"kabala@headspace.org.il","emailLabel2":"Bat Yam","email3":"